const fs=require('fs'),p=require('path'),b=process.argv[2],rd=n=>JSON.parse(fs.readFileSync(p.join(b,n),'utf8').replace(/^\uFEFF/,''));for(let n of [1,2,3,4,5]){let d=rd('A0'+n+'_raport.json');console.log('ZONE'+n,Array.isArray(d.evidence_index)?d.evidence_index.length:Object.keys(d.evidence_index||{}).length,Object.keys(d.evidence_index||{})[0]);for(let f of d.findings.slice(0,1)) console.log('first shape',Object.keys(f));if(n===4||n===5){console.log('SRC',JSON.stringify(d.evidence_index).slice(0,900));console.log('productlimits:',JSON.stringify(d.limits||d.limitations).slice(0,500));}}
const a=rd('A12_raport.json');console.log('zone handoffs',JSON.stringify(a.zone_handoffs).slice(0,500));
